'use strict';
// One persisted task record supplies both the maintenance queue and the user view.
const V24TASK={detail:null};
function v24TaskChoices(t){const out=['审核中','待接单','审核未通过','已取消'];if(t.worker)out.push('已接单');if(t.worker&&t.completionPacket)out.push('待确认完成','已完成');return [...new Set([t.status,...out])]}
function v24UpdateTask(x){v18RequireMaintainer();const key=v9StorageKey('sy-v7-tasks');if(x.storageKey!==key)throw Error('场景已变化，请重新打开任务后保存');const rows=v9StoreBase(key),t=rows.find(t=>t.id===x.id);if(!t)throw Error('任务已不存在');if(String(t.updated||t.created)!==x.expectedUpdated||Number(t.revision||0)!==Number(x.expectedRevision))throw Error('任务已被更新，请重新打开处理窗口');if(V9.active&&Date.parse(t.updated)>businessNow().getTime())throw Error('请将历史时刻推进到该任务最新处理时间');if(!v24TaskChoices(t).includes(x.status))throw Error('该任务缺少此阶段所需的接单或完成材料');const note=String(x.note||'').trim();if(note.length<5)throw Error('请填写至少5字的处理说明');if(x.status==='待接单'&&t.deadline&&v11Date(t.deadline)<=businessNow())throw Error('接单截止时间已过，请退回发布者修改');const now=businessNow().toISOString(),old=t.status;t.history=t.history||[];if(t.history.length&&!t.history.at(-1).snapshot)t.history.at(-1).snapshot=v14TaskState(t);Object.assign(t,{status:x.status,auditNote:note,updated:now,revision:Number(t.revision||0)+1});if(['审核中','待接单','审核未通过'].includes(t.status)){delete t.worker;delete t.workerName;delete t.completion;delete t.completionPacket;}t.history.push({time:now,actual_time:new Date().toISOString(),action:'maint-status',status:t.status,note,snapshot:v14TaskState(t)});if(!v9SaveBase(key,rows))throw Error('保存失败，未更新任务');v3SaveIdentity('maintainer');v3Log('更新任务状态',t.id,old+' → '+t.status+'；'+note);v16Notify('tasks','任务状态更新',t.title+'：'+t.status);return t}
function v24TaskHandle(id){v18RequireMaintainer();const t=v9StoreBase(v9StorageKey('sy-v7-tasks')).find(t=>t.id===id);if(!t)return toast('任务已不存在');V24TASK.detail=null;vDialog(v20Text('处理任务状态','Update task status'),`<h3 data-original>${esc(t.title)}</h3><p>${v20Text('当前状态：','Current status: ')}${esc(t.status)}</p><form id="v24-task-status" class="feedbackform"><input type="hidden" name="id" value="${esc(id)}"><input type="hidden" name="storageKey" value="${esc(v9StorageKey('sy-v7-tasks'))}"><input type="hidden" name="expectedUpdated" value="${esc(t.updated||t.created)}"><input type="hidden" name="expectedRevision" value="${Number(t.revision||0)}"><label>${v20Text('新的任务状态','New task status')}<select name="status">${v24TaskChoices(t).map(s=>`<option ${s===t.status?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label class="full">${v20Text('处理说明（游客可见）','Explanation visible to the user')}<textarea name="note" required minlength="5"></textarea></label><button class="primary">${v20Text('保存并同步任务状态','Save and sync task status')}</button></form><p>${v20Text('保存后更新游客端的任务卡片、详情和时间线。同一浏览器的其他标签页自动更新；现在与历史使用各自的任务记录。','Saving updates the user task card, details and timeline. Other tabs in this browser update automatically; current and historical records are separate.')}</p>`)}
const v24ReviewBase=v14TaskReview;v14TaskReview=function(){return v24ReviewBase().replace('<label>任务状态<select','<label>筛选任务状态（不修改任务）<select')};
// Use task card IDs directly rather than nested markup or queue-filter values.
const v24CardBase=v14TaskCard;v14TaskCard=function(t){let html=v24CardBase(t);if(V3.role==='maintainer')html=html.replace('</article>',`<button data-v24-task="${esc(t.id)}">${v20Text('处理任务状态','Update task status')}</button></article>`);else if(t.auditNote&&t.status!=='审核未通过')html=html.replace('</article>',`<p class="handlingnote"><b>${v20Text('维护处理说明：','Maintenance note: ')}</b><span data-original>${esc(t.auditNote)}</span></p><small>${dateText(t.updated)}</small></article>`);return html};v7TaskCard=v14TaskCard;
const v24DetailBase=v14TaskDetail;v14TaskDetail=function(id,confirm=false){V24TASK.detail={id,confirm,key:v9StorageKey('sy-v7-tasks')};return v24DetailBase(id,confirm)};
document.addEventListener('click',e=>{const b=e.target.closest('[data-v24-task]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();try{v24TaskHandle(b.dataset.v24Task)}catch(err){toast(err.message)}},true);
document.addEventListener('submit',e=>{if(vFormId(e.target)!=='v24-task-status')return;e.preventDefault();e.stopImmediatePropagation();try{v24UpdateTask(Object.fromEntries(new FormData(e.target)));document.getElementById('source-dialog')?.close();vRender();toast(v20Text('任务状态已保存，游客端记录同步更新','Task saved; user records updated'))}catch(err){toast(err.message)}},true);
function v24RefreshTasks(){const d=document.getElementById('source-dialog'),detail=V24TASK.detail;if(d?.open){if(V3.role==='user'&&detail?.key===v9StorageKey('sy-v7-tasks')&&!d.querySelector('form')){vRender();v14TaskDetail(detail.id,detail.confirm)}return}vRender()}
window.addEventListener('storage',e=>{if(e.key===v9StorageKey('sy-v7-tasks')){v24RefreshTasks();toast(v20Text('任务记录已同步更新','Task records updated'))}});
window.addEventListener('focus',()=>{if(V3.role==='maintainer'&&V3.page==='tasks'||V3.role==='user'&&V2.page==='community')v24RefreshTasks()});
Object.assign(V18EN,{'筛选任务状态（不修改任务）':'Filter tasks (does not change status)','新的任务状态':'New task status','处理任务状态':'Update task status','处理说明（游客可见）':'Explanation visible to the user','保存并同步任务状态':'Save and sync task status','维护处理说明：':'Maintenance note: '});
